<?php
namespace App\Console\Commands;use App\Models\DriverProfile;use App\Models\TripIncident;use Illuminate\Console\Command;use Illuminate\Support\Facades\Cache;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Storage;
class OperationsCheck extends Command{protected $signature='ops:check {--json}';protected $description='Checks operational dependencies and urgent queues';public function handle():int{$checks=[];try{DB::select('select 1');$checks['database']='ok';}catch(\Throwable){$checks['database']='failed';}try{$key='ops:'.bin2hex(random_bytes(5));Cache::put($key,1,10);$checks['cache']=Cache::pull($key)===1?'ok':'failed';}catch(\Throwable){$checks['cache']='failed';}try{$path='health/'.bin2hex(random_bytes(5));$disk=Storage::disk(config('filesystems.private'));$disk->put($path,'ok');$disk->delete($path);$checks['storage']='ok';}catch(\Throwable){$checks['storage']='failed';}$checks['failed_jobs']=(int)DB::table('failed_jobs')->count();$checks['critical_incidents']=TripIncident::whereIn('status',['open','in_review'])->where('severity','critical')->count();$checks['documents_expiring_30d']=DriverProfile::where('verification_status','approved')->where(function($q){$date=now()->addDays(30)->toDateString();$q->whereDate('license_expires_at','<=',$date)->orWhereDate('soat_expires_at','<=',$date)->orWhereDate('technical_review_expires_at','<=',$date);})->count();$ok=$checks['database']==='ok'&&$checks['cache']==='ok'&&$checks['storage']==='ok'&&$checks['failed_jobs']===0&&$checks['critical_incidents']===0;if($this->option('json'))$this->line(json_encode(['ok'=>$ok,'checks'=>$checks]));else $this->table(['check','value'],collect($checks)->map(fn($v,$k)=>[$k,$v])->values()->all());return $ok?self::SUCCESS:self::FAILURE;}}